export default "<template>\n  <Menu v-if=\"fixedMenuButtons\" :buttons=\"fixedMenuButtons\" />\n</template>\n<script>\nimport Menu from './Menu.vue'\nimport { createEditorButton } from '../utils'\n\nexport default {\n  name: 'TextEditorFixedMenu',\n  props: ['buttons'],\n  components: { Menu },\n  inject: ['editor'],\n  computed: {\n    fixedMenuButtons() {\n      if (!this.buttons) return false\n      let buttons\n      if (Array.isArray(this.buttons)) {\n        buttons = [...this.buttons]\n      } else {\n        buttons = [\n          'Paragraph',\n          [\n            'Heading 1',\n            'Heading 2',\n            'Heading 3',\n            'Heading 4',\n            'Heading 5',\n            'Heading 6',\n          ],\n          'Separator',\n          'Bold',\n          'Italic',\n          'Strikethrough',\n          'Link',\n          'FontColor',\n          'Separator',\n          'Bullet List',\n          'Numbered List',\n          'Task List',\n          'Separator',\n          'Align Left',\n          'Align Center',\n          'Align Right',\n          'Separator',\n          'Image',\n          'Video',\n          'Blockquote',\n          'Code',\n          'Iframe',\n          'Separator',\n          'Horizontal Rule',\n          [\n            'InsertTable',\n            'AddColumnBefore',\n            'AddColumnAfter',\n            'DeleteColumn',\n            'AddRowBefore',\n            'AddRowAfter',\n            'DeleteRow',\n            'MergeCells',\n            'SplitCell',\n            'ToggleHeaderColumn',\n            'ToggleHeaderRow',\n            'ToggleHeaderCell',\n            'DeleteTable',\n          ],\n          'Separator',\n          'TableOfContents',\n          'Separator',\n          'Undo',\n          'Redo',\n        ]\n      }\n      return buttons.map(createEditorButton)\n    },\n  },\n}\n</script>\n"