export default "<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { EditorContent } from '@tiptap/vue-3'\nimport { Button, TextEditor, TextEditorFixedMenu } from 'frappe-ui'\n\nconst customValue = ref('')\nconst customButtons = [\n  'Paragraph',\n  ['Heading 2', 'Heading 3', 'Heading 4'],\n  'Separator',\n  'Bold',\n  'Italic',\n  'Separator',\n  'Bullet List',\n  'Numbered List',\n  'Separator',\n  'Link',\n  'Image',\n]\n</script>\n\n<template>\n  <TextEditor\n    ref=\"textEditor\"\n    editor-class=\"prose-sm max-w-none min-h-[4rem]\"\n    :content=\"customValue\"\n    @change=\"(val) => (customValue.value = val)\"\n    :starterkit-options=\"{ heading: { levels: [2, 3, 4] } }\"\n    placeholder=\"Write something amazing...\"\n  >\n    <template v-slot:editor=\"{ editor }\">\n      <EditorContent\n        class=\"max-h-[50vh] overflow-y-auto border rounded-lg p-4\"\n        :editor=\"editor\"\n      />\n    </template>\n\n    <template v-slot:bottom>\n      <div\n        class=\"mt-2 flex flex-col justify-between sm:flex-row sm:items-center\"\n      >\n        <TextEditorFixedMenu\n          class=\"-ml-1 overflow-x-auto\"\n          :buttons=\"customButtons\"\n        />\n        <div class=\"mt-2 flex items-center justify-end space-x-2 sm:mt-0\">\n          <Button>Cancel</Button>\n          <Button variant=\"solid\">Submit</Button>\n        </div>\n      </div>\n    </template>\n  </TextEditor>\n</template>\n"