export default "<template>\n  <div>\n    <input\n      ref=\"input\"\n      type=\"file\"\n      :accept=\"fileTypes\"\n      class=\"hidden\"\n      @change=\"onFileAdd\"\n    />\n    <slot\n      v-bind=\"{\n        file,\n        uploading,\n        progress,\n        uploaded,\n        message,\n        error,\n        total,\n        success,\n        openFileSelector,\n      }\"\n    >\n      <Button @click=\"openFileSelector\" :loading=\"uploading\">\n        {{ uploading ? `Uploading ${progress}%` : 'Upload File' }}\n      </Button>\n    </slot>\n  </div>\n</template>\n\n<script>\nimport { Button } from '../Button'\nimport FileUploadHandler from '../../utils/fileUploadHandler'\n\nexport default {\n  name: 'FileUploader',\n  props: {\n    fileTypes: {\n      type: [String, Array],\n    },\n    uploadArgs: {\n      type: Object,\n    },\n    validateFile: {\n      type: Function,\n      default: null,\n    },\n  },\n  data() {\n    return {\n      uploader: null,\n      uploading: false,\n      uploaded: 0,\n      error: null,\n      message: '',\n      total: 0,\n      file: null,\n      finishedUploading: false,\n    }\n  },\n  computed: {\n    progress() {\n      let value = Math.floor((this.uploaded / this.total) * 100)\n      return isNaN(value) ? 0 : value\n    },\n    success() {\n      return this.finishedUploading && !this.error\n    },\n  },\n  methods: {\n    inputRef() {\n      return this.$refs['input']\n    },\n    openFileSelector() {\n      this.$refs['input'].click()\n    },\n    async onFileAdd(e) {\n      this.error = null\n      this.file = e.target.files[0]\n\n      if (this.file && this.validateFile) {\n        try {\n          let message = await this.validateFile(this.file)\n          if (message) {\n            this.error = message\n          }\n        } catch (error) {\n          this.error = error\n        }\n      }\n\n      if (!this.error) {\n        this.uploadFile(this.file)\n      }\n    },\n    async uploadFile(file) {\n      this.error = null\n      this.uploaded = 0\n      this.total = 0\n\n      this.uploader = new FileUploadHandler()\n      this.uploader.on('start', () => {\n        this.uploading = true\n      })\n      this.uploader.on('progress', (data) => {\n        this.uploaded = data.uploaded\n        this.total = data.total\n      })\n      this.uploader.on('error', () => {\n        this.uploading = false\n        this.error = 'Error Uploading File'\n      })\n      this.uploader.on('finish', () => {\n        this.uploading = false\n        this.finishedUploading = true\n      })\n      this.uploader\n        .upload(file, this.uploadArgs || {})\n        .then((data) => {\n          this.$emit('success', data)\n        })\n        .catch((error) => {\n          this.uploading = false\n          let errorMessage = 'Error Uploading File'\n          if (error?._server_messages) {\n            errorMessage = JSON.parse(\n              JSON.parse(error._server_messages)[0],\n            ).message\n          } else if (error?.exc) {\n            errorMessage = JSON.parse(error.exc)[0].split('\\n').slice(-2, -1)[0]\n          }\n          this.error = errorMessage\n          this.$emit('failure', error)\n        })\n    },\n  },\n  expose: ['inputRef'],\n}\n</script>\n"