export default "<script setup>\nimport { h, reactive } from 'vue'\n\nimport { Avatar, ListView } from 'frappe-ui'\n\nconst columns = reactive([\n  {\n    label: 'Name',\n    key: 'name',\n    width: 3,\n    getLabel: ({ row }) => row.name,\n    prefix: ({ row }) =>\n      h(Avatar, { shape: 'circle', image: row.user_image, size: 'sm' }),\n  },\n  { label: 'Email', key: 'email', width: '200px' },\n  { label: 'Role', key: 'role' },\n  { label: 'Status', key: 'status' },\n])\n\nconst rows = [\n  {\n    id: 1,\n    name: 'John Doe',\n    email: 'john@doe.com',\n    status: 'Active',\n    role: 'Developer',\n    user_image: 'https://avatars.githubusercontent.com/u/499550',\n  },\n  {\n    id: 2,\n    name: 'Jane Doe',\n    email: 'jane@doe.com',\n    status: 'Inactive',\n    role: 'HR',\n    user_image: 'https://avatars.githubusercontent.com/u/499120',\n  },\n]\n</script>\n\n<template>\n  <ListView\n    class=\"h-[150px]\"\n    :columns=\"columns\"\n    :rows=\"rows\"\n    :options=\"{\n      getRowRoute: (row) => ({\n        name: 'User',\n        params: { userId: row.id },\n      }),\n      selectable: true,\n      showTooltip: true,\n      resizeColumn: true,\n    }\"\n    row-key=\"id\"\n  />\n</template>\n"