export default "<template>\n  <div\n    class=\"flex max-h-[140px] items-center gap-2 overflow-hidden bg-surface-white text-ink-gray-8 px-6 pt-5\"\n    :class=\"config.delta ? 'pb-6' : 'pb-3'\"\n  >\n    <slot name=\"body\">\n      <div class=\"flex w-full flex-col\">\n        <slot name=\"title\">\n          <span class=\"truncate text-sm font-medium text-ink-gray-5\">\n            {{ config.title }}\n          </span>\n        </slot>\n        <slot name=\"subtitle\" v-bind=\"{ formatValue }\">\n          <div\n            class=\"flex flex-1 items-center gap-0.5 flex-shrink-0 truncate text-[24px] text-ink-gray-6 font-semibold leading-10\"\n          >\n            <div\n              v-if=\"config.prefix\"\n              v-html=\"config.prefix\"\n              class=\"size-4 table\"\n            />\n            {{ formatValue(config.value, 1, true) }}{{ config.suffix }}\n          </div>\n        </slot>\n        <slot name=\"delta\" v-bind=\"{ formatValue }\">\n          <div\n            v-if=\"config.delta\"\n            class=\"flex items-center gap-0.5 text-xs font-medium\"\n            :class=\"[\n              config.negativeIsBetter\n                ? config.delta >= 0\n                  ? 'text-ink-red-4'\n                  : 'text-ink-green-3'\n                : config.delta >= 0\n                  ? 'text-ink-green-3'\n                  : 'text-ink-red-4',\n            ]\"\n          >\n            <span class=\"\">\n              {{ config.delta >= 0 ? '↑' : '↓' }}\n            </span>\n            <span>\n              {{ config.deltaPrefix }}{{ formatValue(config.delta, 1, true)\n              }}{{ config.deltaSuffix }}\n            </span>\n          </div>\n        </slot>\n      </div>\n    </slot>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { formatValue } from './helpers'\nimport { NumberChartConfig } from './types'\n\ndefineProps<{ config: NumberChartConfig }>()\n</script>\n"