export default "<script setup lang=\"ts\">\nimport { EChartsOption, init } from 'echarts'\nimport { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'\nimport debounce from '../../utils/debounce'\n\nconst props = defineProps<{\n  options: EChartsOption\n  events?: {\n    click: (params: any) => void\n  }\n  error?: string\n  class?: string\n}>()\n\nlet chart: echarts.ECharts\nconst chartDiv = ref<HTMLDivElement>()\n\nconst chartClass = computed(() => {\n  const defaults =\n    'h-full w-full min-w-[300px] md:min-w-[400px] min-h-[300px] px-4 py-2'\n  return props.class || defaults\n})\n\nonMounted(() => {\n  if (!chartDiv.value) return\n\n  chart = init(chartDiv.value, 'light', { renderer: 'svg' })\n  chart.setOption({ ...props.options }, true)\n\n  if (props.events?.click) {\n    chart.on('click', props.events.click)\n  }\n\n  const resizeDebounce = debounce(() => {\n    chart.resize({\n      animation: {\n        duration: 300,\n      },\n    })\n  }, 250)\n\n  let resizeObserver = new ResizeObserver(resizeDebounce)\n  setTimeout(() => resizeObserver.observe(chartDiv.value!), 500)\n  onBeforeUnmount(() => resizeObserver.unobserve(chartDiv.value!))\n})\n\nwatch(\n  () => props.options,\n  (newOptions) => {\n    if (chart) {\n      chart.setOption(newOptions, true)\n    }\n  },\n  { deep: true },\n)\n</script>\n\n<template>\n  <div ref=\"chartDiv\" v-show=\"!error\" :class=\"chartClass\"></div>\n  <div\n    v-show=\"error\"\n    class=\"flex h-full w-full items-center justify-center text-center text-ink-red-3\"\n  >\n    Error: {{ error }}\n  </div>\n</template>\n"