export default "<template>\n  <Dialog v-model=\"showDialog\" :options=\"{ title }\" @close=\"closeDialog\">\n    <template #body-content>\n      <div class=\"space-y-4\">\n        <p\n          class=\"text-p-base text-ink-gray-6\"\n          v-if=\"message\"\n          v-html=\"message\"\n        />\n      </div>\n    </template>\n    <template #actions>\n      <Button class=\"w-full\" v-bind=\"primaryActionProps\" />\n    </template>\n  </Dialog>\n</template>\n<script>\nimport { Button } from './Button'\nimport { Dialog } from './Dialog'\n\nexport default {\n  name: 'ConfirmDialog',\n  props: {\n    title: {\n      type: String,\n    },\n    message: {\n      type: String,\n    },\n    onConfirm: {\n      type: Function,\n      default: null,\n    },\n    onCancel: {\n      type: Function,\n      default: null,\n    },\n  },\n  expose: ['show', 'hide'],\n  components: {\n    Dialog,\n    Button,\n  },\n  data() {\n    return {\n      showDialog: true,\n      isLoading: false,\n    }\n  },\n  methods: {\n    handleConfirmation() {\n      try {\n        this.onConfirm?.({\n          hideDialog: this.hide,\n        })\n      } finally {\n        this.isLoading = false\n      }\n    },\n    show() {\n      this.showDialog = true\n    },\n    closeDialog() {\n      this.hide()\n      this.onCancel?.()\n    },\n    hide() {\n      this.showDialog = false\n    },\n  },\n  computed: {\n    primaryActionProps() {\n      return {\n        label: 'Confirm',\n        variant: 'solid',\n        loading: this.isLoading,\n        onClick: this.handleConfirmation,\n      }\n    },\n  },\n}\n</script>\n"