export default "<template>\n  <RadioGroup v-model=\"value\">\n    <div\n      class=\"flex space-x-0.5 rounded-md bg-surface-gray-2 h-7 items-center px-[1px] text-sm\"\n    >\n      <RadioGroupOption\n        as=\"div\"\n        v-for=\"button in buttons\"\n        :key=\"button.label\"\n        :disabled=\"button.disabled\"\n        :value=\"button.value ?? button.label\"\n        v-slot=\"{ active, checked }\"\n      >\n        <Button\n          @click=\"button.onClick\"\n          v-bind=\"button\"\n          class=\"!h-6.5\"\n          :class=\"[\n            active ? 'ring-outline-gray-2 focus-visible:ring' : '',\n            checked && '!bg-surface-white',\n            button.disabled\n              ? ''\n              : checked\n                ? ' text-ink-gray-8 shadow'\n                : '!text-ink-gray-5',\n          ]\"\n        >\n          <RadioGroupLabel\n            as=\"span\"\n            class=\"flex h-4 items-center\"\n            v-show=\"button.label && !button.hideLabel\"\n            >{{ button.label }}</RadioGroupLabel\n          >\n        </Button>\n      </RadioGroupOption>\n    </div>\n  </RadioGroup>\n</template>\n<script>\nimport { RadioGroup, RadioGroupLabel, RadioGroupOption } from '@headlessui/vue'\nimport FeatherIcon from '../FeatherIcon.vue'\nimport Button from '../Button/Button.vue'\n\nexport default {\n  name: 'TabButtons',\n  props: {\n    buttons: {\n      type: Array,\n      required: true,\n    },\n    modelValue: {\n      type: [String, Boolean, Number],\n    },\n  },\n  emits: ['update:modelValue'],\n  components: {\n    Button,\n    FeatherIcon,\n    RadioGroup,\n    RadioGroupOption,\n    RadioGroupLabel,\n  },\n  computed: {\n    value: {\n      get() {\n        return this.modelValue\n      },\n      set(value) {\n        this.$emit('update:modelValue', value)\n      },\n    },\n  },\n}\n</script>\n"