export default "<template>\n  <BubbleMenu v-if=\"bubbleMenuButtons\" class=\"bubble-menu rounded-md z-[100]\"\n    :class=\"bubbleMenuButtons.length > 1 && 'shadow-sm'\" :editor=\"editor\" v-bind=\"options\">\n    <Menu class=\"rounded\" :class=\"bubbleMenuButtons.length > 1 && 'shadow-lg'\" :buttons=\"bubbleMenuButtons\" />\n  </BubbleMenu>\n</template>\n<script>\nimport { BubbleMenu } from '@tiptap/vue-3/menus'\nimport { createEditorButton } from '../utils'\nimport Menu from './Menu.vue'\n\nexport default {\n  name: 'TextEditorBubbleMenu',\n  props: ['buttons', 'options'],\n  components: { BubbleMenu, Menu },\n  inject: ['editor'],\n  computed: {\n    bubbleMenuButtons() {\n      if (!this.buttons) return false\n\n      let buttons\n      if (Array.isArray(this.buttons)) {\n        buttons = this.buttons\n      } else {\n        buttons = [\n          'Paragraph',\n          'Heading 2',\n          'Heading 3',\n          'Separator',\n          'Bold',\n          'Italic',\n          'Strikethrough',\n          'FontColor',\n          'Link',\n          'Separator',\n          'Bullet List',\n          'Numbered List',\n          'Task List',\n          'Separator',\n          'Align Left',\n          'Align Center',\n          'Align Right',\n          'Separator',\n          'Image',\n          'Video',\n          'Blockquote',\n          'Code',\n          [\n            'InsertTable',\n            'AddColumnBefore',\n            'AddColumnAfter',\n            'DeleteColumn',\n            'AddRowBefore',\n            'AddRowAfter',\n            'DeleteRow',\n            'MergeCells',\n            'SplitCell',\n            'ToggleHeaderColumn',\n            'ToggleHeaderRow',\n            'ToggleHeaderCell',\n            'DeleteTable',\n          ],\n        ]\n      }\n      return buttons.map(createEditorButton)\n    },\n  },\n}\n</script>\n"