export default "<script setup lang=\"ts\">\nimport {\n  TooltipProvider,\n  TooltipRoot,\n  TooltipPortal,\n  TooltipTrigger,\n  TooltipContent,\n  TooltipArrow,\n} from 'reka-ui'\nimport { computed } from 'vue'\nimport type { TooltipProps } from './types'\n\ndefineOptions({\n  inheritAttrs: false,\n})\n\nconst props = withDefaults(defineProps<TooltipProps>(), {\n  text: '',\n  placement: 'top',\n  hoverDelay: 0.5,\n  arrowClass: 'fill-surface-gray-7',\n  disabled: false,\n})\n\nconst delayDuration = computed(() => props.hoverDelay * 1000)\n\ndefineSlots<{\n  /**\n   * Default trigger slot.\n   * Wraps the element that the tooltip is attached to.\n   */\n  default?: () => any\n\n  /**\n   * Slot for fully custom tooltip body.\n   * Replaces the default tooltip container entirely.\n   */\n  body?: () => any\n\n  /**\n   * Slot for tooltip content text.\n   * Used inside the default tooltip body.\n   */\n  content?: () => any\n}>()\n\n</script>\n\n<template>\n  <slot v-if=\"disabled\" />\n  <TooltipProvider v-else :delayDuration=\"delayDuration\">\n    <TooltipRoot>\n      <TooltipTrigger as-child>\n        <slot />\n      </TooltipTrigger>\n      <TooltipPortal>\n        <TooltipContent\n          v-if=\"props.text || $slots.body || $slots.content\"\n          :side=\"props.placement\"\n          :side-offset=\"4\"\n          class=\"z-[100]\"\n        >\n          <slot name=\"body\">\n            <div\n              class=\"rounded bg-surface-gray-7 px-2 py-1 text-xs text-ink-white shadow-xl\"\n            >\n              <slot name=\"content\">{{ props.text }}</slot>\n            </div>\n          </slot>\n          <TooltipArrow :class=\"props.arrowClass\" :width=\"8\" :height=\"4\" />\n        </TooltipContent>\n      </TooltipPortal>\n    </TooltipRoot>\n  </TooltipProvider>\n</template>\n"