export default "<template>\n  <PopoverRoot v-model:open=\"isOpen\" @update:open=\"onUpdateOpen\">\n    <PopoverAnchor asChild>\n      <div\n        ref=\"anchorRef\"\n        :class=\"['flex', $attrs.class]\"\n        :style=\"($attrs.style as StyleValue)\"\n        @mouseover=\"onMouseover\"\n        @mouseleave=\"onMouseleave\"\n      >\n        <slot\n          name=\"target\"\n          v-bind=\"{\n            togglePopover,\n            updatePosition,\n            open,\n            close,\n            isOpen,\n          }\"\n        />\n      </div>\n    </PopoverAnchor>\n    <PopoverPortal>\n      <PopoverContent\n        :side=\"placementSide\"\n        :align=\"placementAlign\"\n        :sideOffset=\"offset\"\n        :style=\"{\n          minWidth: matchTargetWidth\n            ? 'var(--reka-popover-trigger-width)'\n            : undefined,\n        }\"\n        :class=\"['PopoverContent', { 'has-transition': hasTransition }]\"\n        @mouseover=\"\n          () => {\n            pointerOverTargetOrPopup = true\n          }\n        \"\n        @mouseleave=\"onMouseleave\"\n        @interact-outside=\"onInteractOutside\"\n      >\n        <div class=\"relative\" :class=\"['body-container', popoverClass]\">\n          <slot\n            name=\"body\"\n            v-bind=\"{ togglePopover, updatePosition, open, close, isOpen }\"\n          >\n            <div class=\"rounded-lg border bg-surface-modal shadow-xl\">\n              <slot\n                name=\"body-main\"\n                v-bind=\"{\n                  togglePopover,\n                  updatePosition,\n                  open,\n                  close,\n                  isOpen,\n                }\"\n              />\n            </div>\n          </slot>\n        </div>\n      </PopoverContent>\n    </PopoverPortal>\n  </PopoverRoot>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref, onUnmounted, type StyleValue } from 'vue'\nimport {\n  PopoverAnchor,\n  PopoverContent,\n  PopoverPortal,\n  PopoverRoot,\n} from 'reka-ui'\nimport { PopoverProps, PopoverEmits } from './types'\n\nconst props = withDefaults(defineProps<PopoverProps>(), {\n  show: undefined,\n  trigger: 'click',\n  hoverDelay: 0,\n  leaveDelay: 0.5,\n  placement: 'bottom-start',\n  popoverClass: '',\n  transition: null,\n  hideOnBlur: true,\n})\n\nconst emit = defineEmits<{\n  (event: 'open'): void\n  (event: 'close'): void\n  (event: 'update:show', value: boolean): void\n}>()\n\ndefineExpose({ open, close })\n\ndefineOptions({\n  inheritAttrs: false,\n})\n\nconst _isOpen = ref(false)\nconst pointerOverTargetOrPopup = ref(false)\nconst hoverTimer = ref<number | null>(null)\nconst leaveTimer = ref<number | null>(null)\nconst anchorRef = ref<HTMLElement | null>(null)\n\nconst isOpen = computed({\n  get: () => (isShowPropPassed.value ? props.show : _isOpen.value),\n\tset: (value: boolean) => {\n\t\tif (!isShowPropPassed.value) {\n\t\t\tif (value !== _isOpen.value) {\n\t\t\t\t_isOpen.value = value\n\t\t\t\tonUpdateOpen(value)\n\t\t\t}\n\t\t}\n\t},\n})\n\nconst isShowPropPassed = computed(() => {\n  return props.show !== undefined\n})\n\nconst placementSide = computed(() => {\n  const [side] = props.placement.split('-')\n  return side as 'top' | 'right' | 'bottom' | 'left'\n})\n\nconst placementAlign = computed(() => {\n  const [, align] = props.placement.split('-')\n  if (!align) return 'center'\n  return align as 'start' | 'center' | 'end'\n})\n\nfunction togglePopover(flag?: boolean | Event) {\n  if (flag instanceof Event) {\n    flag = undefined\n  }\n  if (flag == null) {\n    flag = !isOpen.value\n  }\n  flag = Boolean(flag)\n  if (flag) {\n    open()\n  } else {\n    close()\n  }\n}\n\nfunction updatePosition() {\n  // not needed\n}\n\nfunction open() {\n  isOpen.value = true\n}\n\nfunction close() {\n  isOpen.value = false\n}\n\nfunction onUpdateOpen(value: boolean) {\n  emit('update:show', value)\n  if (value) {\n    emit('open')\n  } else {\n    emit('close')\n  }\n}\n\nfunction onMouseover() {\n  pointerOverTargetOrPopup.value = true\n  if (leaveTimer.value) {\n    clearTimeout(leaveTimer.value)\n    leaveTimer.value = null\n  }\n  if (props.trigger === 'hover') {\n    if (props.hoverDelay) {\n      hoverTimer.value = setTimeout(\n        () => {\n          if (pointerOverTargetOrPopup.value) {\n            open()\n          }\n        },\n        Number(props.hoverDelay) * 1000,\n      ) as unknown as number\n    } else {\n      open()\n    }\n  }\n}\n\nfunction onMouseleave() {\n  pointerOverTargetOrPopup.value = false\n  if (hoverTimer.value) {\n    clearTimeout(hoverTimer.value)\n    hoverTimer.value = null\n  }\n  if (props.trigger === 'hover') {\n    if (leaveTimer.value) {\n      clearTimeout(leaveTimer.value)\n    }\n    if (props.leaveDelay) {\n      leaveTimer.value = setTimeout(\n        () => {\n          if (!pointerOverTargetOrPopup.value) {\n            close()\n          }\n        },\n        Number(props.leaveDelay) * 1000,\n      ) as unknown as number\n    } else {\n      if (!pointerOverTargetOrPopup.value) {\n        close()\n      }\n    }\n  }\n}\n\nfunction onInteractOutside(event: Event) {\n  if (!props.hideOnBlur) {\n    event.preventDefault()\n    return\n  }\n\n  // Check if the click is on the trigger/anchor element\n  const target = event.target as Element\n  if (\n    anchorRef.value &&\n    (anchorRef.value.contains(target) || anchorRef.value === target)\n  ) {\n    event.preventDefault()\n    return\n  }\n}\n\nconst hasTransition = computed(() => {\n  return props.transition === 'default'\n})\n\n// Cleanup timers on unmount\nonUnmounted(() => {\n  if (hoverTimer.value) {\n    clearTimeout(hoverTimer.value)\n  }\n  if (leaveTimer.value) {\n    clearTimeout(leaveTimer.value)\n  }\n})\n\ndefineSlots<{\n  /** Content of the trigger/anchor element */\n  target?: (props: {\n    togglePopover: () => void\n    updatePosition: () => void\n    open: () => void\n    close: () => void\n    isOpen: boolean\n  }) => any\n\n  /** Main content of the popover body */\n  body?: (props: {\n    togglePopover: () => void\n    updatePosition: () => void\n    open: () => void\n    close: () => void\n    isOpen: boolean\n  }) => any\n\n  /** Inner content inside the default body container */\n  'body-main'?: (props: {\n    togglePopover: () => void\n    updatePosition: () => void\n    open: () => void\n    close: () => void\n    isOpen: boolean\n  }) => any\n}>()\n\n</script>\n\n<style>\n/* Default transition animations */\n@keyframes popover-enter {\n  from {\n    opacity: 0;\n    transform: translateY(4px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n@keyframes popover-exit {\n  from {\n    opacity: 1;\n    transform: translateY(0);\n  }\n  to {\n    opacity: 0;\n    transform: translateY(4px);\n  }\n}\n\n/* Default transition */\n.PopoverContent.has-transition[data-state='open'] {\n  animation: popover-enter 150ms ease-out;\n}\n\n.PopoverContent.has-transition[data-state='closed'] {\n  animation: popover-exit 150ms ease-in;\n}\n</style>\n"