export default "<template>\n  <Button\n    :label=\"props.label\"\n    @click=\"handleClick\"\n    class=\"!w-full focus-visible:ring-0 focus:outline-none\"\n    :class=\"\n      props.isActive\n        ? '!bg-surface-selected shadow-sm'\n        : 'hover:bg-surface-gray-2'\n    \"\n    variant=\"ghost\"\n    :accesskey=\"props.accessKey\"\n  >\n    <template #icon>\n      <div\n        class=\"flex w-full items-center justify-between transition-all ease-in-out px-2 py-1\"\n      >\n        <div class=\"flex items-center truncate\">\n          <Tooltip\n            :text=\"props.label\"\n            placement=\"right\"\n            :disabled=\"!isCollapsed\"\n          >\n            <span class=\"grid flex-shrink-0 place-items-center\">\n              <slot name=\"icon\">\n                <span\n                  v-if=\"props.icon && typeof props.icon === 'string'\"\n                  class=\"size-4 text-ink-gray-6\"\n                >\n                  {{ props.icon }}\n                </span>\n                <component\n                  v-else\n                  :is=\"props.icon\"\n                  class=\"size-4 text-ink-gray-6\"\n                />\n              </slot>\n            </span>\n          </Tooltip>\n          <Tooltip\n            :text=\"props.label\"\n            placement=\"right\"\n            :disabled=\"isCollapsed\"\n            :hoverDelay=\"1.5\"\n          >\n            <span\n              class=\"flex-1 flex-shrink-0 truncate text-sm transition-all ease-in-out\"\n              :class=\"\n                isCollapsed\n                  ? 'ml-0 w-0 overflow-hidden opacity-0'\n                  : 'ml-2 w-auto opacity-100'\n              \"\n            >\n              {{ props.label }}\n            </span>\n          </Tooltip>\n        </div>\n        <div\n          class=\"transition-all ease-in-out\"\n          :class=\"\n            isCollapsed\n              ? 'ml-0 w-0 overflow-hidden opacity-0'\n              : 'ml-auto w-auto opacity-100'\n          \"\n        >\n          <slot name=\"suffix\">\n            <span v-if=\"props.suffix\" class=\"text-sm text-ink-gray-4\">\n              {{ props.suffix }}\n            </span>\n          </slot>\n        </div>\n      </div>\n    </template>\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { inject } from 'vue'\nimport { useRouter } from 'vue-router'\nimport Button from '../Button/Button.vue'\nimport Tooltip from '../Tooltip/Tooltip.vue'\nimport { SidebarItemProps } from './types'\n\nconst props = defineProps<SidebarItemProps>()\nconst isCollapsed = inject('isSidebarCollapsed', false)\n\nconst router = useRouter()\nfunction handleClick() {\n  if (props.onClick) {\n    props.onClick()\n  } else if (props.to) {\n    router.replace(props.to)\n  }\n}\n</script>\n"