export default "<template>\n  <template>\n    <Dialog\n      v-model=\"show\"\n      :options=\"{ size: 'xl', position: 'top' }\"\n      @after-leave=\"searchQuery = ''\"\n    >\n      <template #body>\n        <div>\n          <Combobox nullable @update:model-value=\"select\">\n            <div class=\"relative\">\n              <div class=\"absolute inset-y-0 left-0 flex items-center pl-4.5\">\n                <FeatherIcon name=\"search\" class=\"h-4 w-4\" />\n              </div>\n              <ComboboxInput\n                placeholder=\"Search\"\n                class=\"w-full border-none bg-transparent py-3 pl-11.5 pr-4.5 text-base text-ink-gray-8 placeholder-ink-gray-4 focus:ring-0\"\n                v-model=\"searchQuery\"\n                autocomplete=\"off\"\n              />\n            </div>\n            <ComboboxOptions\n              class=\"max-h-96 overflow-auto border-t border-gray-100\"\n              static\n              :hold=\"true\"\n            >\n              <div\n                class=\"mb-2 mt-4.5 first:mt-3\"\n                v-for=\"(group, index) in groups\"\n                :key=\"group.title\"\n              >\n                <div\n                  class=\"mb-2.5 px-4.5 text-base text-ink-gray-5\"\n                  v-if=\"!group.hideTitle\"\n                >\n                  {{ group.title }}\n                </div>\n                <ComboboxOption\n                  v-for=\"item in group.items\"\n                  :key=\"item.name\"\n                  v-slot=\"{ active }\"\n                  :value=\"item\"\n                  class=\"px-2.5\"\n                  :disabled=\"item.disabled\"\n                >\n                  <component\n                    :is=\"group.component\"\n                    :item=\"item\"\n                    :active=\"active\"\n                  />\n                </ComboboxOption>\n              </div>\n            </ComboboxOptions>\n          </Combobox>\n        </div>\n      </template>\n    </Dialog>\n  </template>\n</template>\n\n<script setup>\nimport {\n  Combobox,\n  ComboboxInput,\n  ComboboxOption,\n  ComboboxOptions,\n} from '@headlessui/vue'\nimport { computed, onBeforeUnmount, onMounted } from 'vue'\n\nconst emit = defineEmits(['update:show', 'update:searchQuery', 'select'])\nconst props = defineProps({\n  show: { type: Boolean, default: false },\n  searchQuery: { type: String, default: '' },\n  groups: { type: Array, default: () => [] },\n})\n\nconst show = computed({\n  get: () => props.show,\n  set: (value) => emit('update:show', value),\n})\n\nconst searchQuery = computed({\n  get: () => props.searchQuery,\n  set: (value) => emit('update:searchQuery', value),\n})\n\nfunction select(item) {\n  emit('select', item)\n  show.value = false\n}\n\nfunction keydownWatcher(e) {\n  if (e.key === 'Escape' && show.value) {\n    show.value = false\n    e.preventDefault()\n  }\n\n  if (\n    e.key === 'k' &&\n    (e.ctrlKey || e.metaKey) &&\n    !e.target.classList.contains('ProseMirror')\n  ) {\n    show.value = true\n    e.preventDefault()\n  }\n}\n\nonMounted(() => window.addEventListener('keydown', keydownWatcher))\nonBeforeUnmount(() => window.removeEventListener('keydown', keydownWatcher))\n</script>\n"