export default "<script setup>\nimport { h, reactive } from 'vue'\nimport { Avatar, Badge, ListView } from 'frappe-ui'\n\nconst cols = reactive([\n  {\n    label: 'Name',\n    key: 'name',\n    width: 3,\n    getLabel: ({ row }) => row.name,\n    prefix: ({ row }) =>\n      h(Avatar, { shape: 'circle', image: row.user_image, size: 'sm' }),\n  },\n  { label: 'Email', key: 'email', width: '200px' },\n  { label: 'Role', key: 'role' },\n  { label: 'Status', key: 'status' },\n])\n\nconst rows = [\n  {\n    id: 1,\n    name: 'John Doe',\n    email: 'john@doe.com',\n    status: 'Active',\n    role: 'Developer',\n    user_image: 'https://avatars.githubusercontent.com/u/499550',\n  },\n  {\n    id: 2,\n    name: 'Jane Doe',\n    email: 'jane@doe.com',\n    status: 'Inactive',\n    role: 'HR',\n    user_image: 'https://avatars.githubusercontent.com/u/499120',\n  },\n]\n</script>\n\n<template>\n  <ListView\n    class=\"h-[250px]\"\n    :columns=\"cols\"\n    :rows=\"rows\"\n    :options=\"{\n      selectable: true,\n      showTooltip: true,\n      resizeColumn: true,\n      emptyState: {\n        title: 'No records found',\n        description: 'Create a new record to get started',\n        button: {\n          label: 'New Record',\n          variant: 'solid',\n          onClick: () => console.log('New Record'),\n        },\n      },\n    }\"\n    row-key=\"id\"\n  >\n    <template #cell=\"{ item, row, column }\">\n      <Badge v-if=\"column.key === 'status'\">{{ item }}</Badge>\n      <span class=\"font-medium text-ink-gray-7\" v-else>{{ item }}</span>\n    </template>\n  </ListView>\n</template>\n"