export default "<template>\n  <Autocomplete\n    placeholder=\"Select an option\"\n    :options=\"options\"\n    :value=\"selection\"\n    @update:query=\"(q) => onUpdateQuery(q)\"\n    @change=\"(v) => (selection = v)\"\n  />\n</template>\n\n<script setup>\nimport { Autocomplete, createListResource } from '../../index'\nimport { computed, ref, watch } from 'vue'\n\nconst props = defineProps({\n  value: {\n    type: String,\n    required: false,\n    default: '',\n  },\n  doctype: {\n    type: String,\n    required: true,\n  },\n  searchField: {\n    type: String,\n    required: false,\n    default: 'name',\n  },\n  labelField: {\n    type: String,\n    required: false,\n    default: 'name',\n  },\n  valueField: {\n    type: String,\n    required: false,\n    default: 'name',\n  },\n  pageLength: {\n    type: Number,\n    required: false,\n    default: 10,\n  },\n})\n\nwatch(\n  () => props.doctype,\n  (value) => {\n    r.doctype = value\n    r.reload()\n  },\n)\n\nconst r = createListResource({\n  doctype: props.doctype,\n  pageLength: props.pageLength,\n  cache: ['link_doctype', props.doctype],\n  auto: true,\n  fields: [props.labelField, props.searchField, props.valueField],\n  onSuccess: () => {\n    selection.value = props.value\n      ? options.value.find((o) => o.value === props.value)\n      : null\n  },\n})\nconst options = computed(\n  () =>\n    r.data?.map((result) => ({\n      label: result[props.labelField],\n      value: result[props.valueField],\n    })) || [],\n)\nconst selection = ref(null)\n\nfunction onUpdateQuery(query) {\n  r.update({\n    filters: {\n      [props.searchField]: ['like', `%${query}%`],\n    },\n  })\n\n  r.reload()\n}\n</script>\n"