export default "<template>\n  <FloatingMenu\n    v-if=\"floatingMenuButtons\"\n    :options=\"{ duration: 100 }\"\n    :editor=\"editor\"\n    class=\"flex\"\n  >\n    <button\n      v-for=\"button in floatingMenuButtons\"\n      :key=\"button.label\"\n      class=\"flex rounded p-1 text-ink-gray-8 transition-colors\"\n      :class=\"\n        button.isActive(editor)\n          ? 'bg-surface-gray-2'\n          : 'hover:bg-surface-gray-2'\n      \"\n      @click=\"() => button.action(editor)\"\n      :title=\"button.label\"\n    >\n      <component v-if=\"button.icon\" :is=\"button.icon\" class=\"h-4 w-4\" />\n      <span class=\"inline-block h-4 min-w-[1rem] text-sm leading-4\" v-else>\n        {{ button.text }}\n      </span>\n    </button>\n  </FloatingMenu>\n</template>\n<script>\nimport { FloatingMenu } from '@tiptap/vue-3/menus'\nimport { createEditorButton } from '../utils'\n\nexport default {\n  name: 'TextEditorFloatingMenu',\n  props: ['buttons'],\n  components: { FloatingMenu },\n  inject: ['editor'],\n  computed: {\n    floatingMenuButtons() {\n      if (!this.buttons) return false\n\n      let buttons\n      if (Array.isArray(this.buttons)) {\n        buttons = this.buttons\n      } else {\n        buttons = [\n          'Paragraph',\n          'Heading 2',\n          'Heading 3',\n          'Bullet List',\n          'Numbered List',\n          'Task List',\n          'Blockquote',\n          'Code',\n          'Horizontal Rule',\n          'TableOfContents',\n        ]\n      }\n      return buttons.map(createEditorButton)\n    },\n  },\n}\n</script>\n"