export default "<script>\nimport { h, mergeProps } from 'vue'\nimport feather from 'feather-icons'\n\nconst validIcons = Object.keys(feather.icons)\n\nexport default {\n  props: {\n    name: {\n      type: String,\n      required: true,\n      validator(value) {\n        const valid = validIcons.includes(value)\n        if (!valid) {\n          console.groupCollapsed(\n            '[frappe-ui] name property for feather-icon must be one of ',\n          )\n          console.dir(validIcons)\n          console.groupEnd()\n        }\n        return valid\n      },\n    },\n    color: {\n      type: String,\n      default: null,\n    },\n    strokeWidth: {\n      type: Number,\n      default: 1.5,\n    },\n  },\n  render() {\n    let icon = feather.icons[this.name]\n    if (!icon) {\n      icon = feather.icons['circle']\n    }\n    return h(\n      'svg',\n      mergeProps(\n        icon.attrs,\n        {\n          fill: 'none',\n          stroke: 'currentColor',\n          color: this.color,\n          'stroke-linecap': 'round',\n          'stroke-linejoin': 'round',\n          'stroke-width': this.strokeWidth,\n          width: null,\n          height: null,\n          class: [icon.attrs.class, 'shrink-0'],\n          innerHTML: icon.contents,\n        },\n        this.$attrs,\n      ),\n    )\n  },\n}\n</script>\n"