export default "<template>\n  <div>\n    <div\n      v-if=\"items.length\"\n      class=\"min-w-40 rounded-lg border bg-surface-white p-1 text-base shadow-lg\"\n    >\n      <button\n        :class=\"[\n          index === selectedIndex ? 'bg-surface-gray-2' : '',\n          'flex w-full items-center whitespace-nowrap rounded-md px-2 py-2 text-sm text-ink-gray-9',\n        ]\"\n        v-for=\"(item, index) in items\"\n        :key=\"index\"\n        @click=\"selectItem(index)\"\n        @mouseover=\"selectedIndex = index\"\n      >\n        {{ item.label }}\n      </button>\n    </div>\n  </div>\n</template>\n\n<script>\nexport default {\n  props: {\n    items: {\n      type: Array,\n      required: true,\n    },\n    command: {\n      type: Function,\n      required: true,\n    },\n  },\n  data() {\n    return {\n      selectedIndex: 0,\n    }\n  },\n  watch: {\n    items() {\n      this.selectedIndex = 0\n    },\n  },\n  methods: {\n    onKeyDown({ event }) {\n      if (event.key === 'ArrowUp') {\n        this.upHandler()\n        return true\n      }\n      if (event.key === 'ArrowDown') {\n        this.downHandler()\n        return true\n      }\n      if (event.key === 'Enter') {\n        this.enterHandler()\n        return true\n      }\n      return false\n    },\n    upHandler() {\n      this.selectedIndex =\n        (this.selectedIndex + this.items.length - 1) % this.items.length\n    },\n    downHandler() {\n      this.selectedIndex = (this.selectedIndex + 1) % this.items.length\n    },\n    enterHandler() {\n      this.selectItem(this.selectedIndex)\n    },\n    selectItem(index) {\n      const item = this.items[index]\n      if (item) {\n        this.command({ id: item.value, label: item.label })\n      }\n    },\n  },\n}\n</script>\n\n<style>\n.item {\n  display: block;\n  margin: 0;\n  width: 100%;\n  text-align: left;\n  background: transparent;\n  border-radius: 0.4rem;\n  border: 1px solid transparent;\n  padding: 0.2rem 0.4rem;\n}\n.item.is-selected {\n  border-color: #000;\n}\n</style>\n"