export default "<template>\n  <node-view-wrapper>\n    <div class=\"code-block-container\">\n      <select\n        class=\"language-selector form-select py-0\"\n        contenteditable=\"false\"\n        v-model=\"selectedLanguage\"\n      >\n        <option :value=\"null\">auto</option>\n        <option disabled>—</option>\n        <option\n          v-for=\"(language, index) in languages\"\n          :value=\"language.value\"\n          :key=\"language.value\"\n        >\n          {{ language.label }}\n        </option>\n      </select>\n      <pre><code><node-view-content /></code></pre>\n    </div>\n  </node-view-wrapper>\n</template>\n\n<script>\nimport { NodeViewContent, nodeViewProps, NodeViewWrapper } from '@tiptap/vue-3'\n\nexport default {\n  components: {\n    NodeViewWrapper,\n    NodeViewContent,\n  },\n  props: nodeViewProps,\n  computed: {\n    selectedLanguage: {\n      get() {\n        return this.node.attrs.language\n      },\n      set(language) {\n        this.updateAttributes({ language })\n      },\n    },\n    languages() {\n      let supportedLanguages = this.extension.options.lowlight.listLanguages()\n      return supportedLanguages\n        .map((language) => {\n          return {\n            label: language,\n            value: language,\n          }\n        })\n        .concat([{ label: 'html', value: 'xml' }])\n        .sort((a, b) => a.label.localeCompare(b.label))\n    },\n  },\n}\n</script>\n\n<style>\n/* CodeBlock styles */\n.code-block {\n  position: relative;\n}\n\n.code-block-container {\n  position: relative;\n}\n\n.language-selector {\n  position: absolute;\n  top: 0.25rem;\n  right: 0.25rem;\n  padding-top: 0;\n  padding-bottom: 0;\n  opacity: 0;\n  z-index: 10;\n  transition-property: opacity;\n  transition-duration: 0.2s;\n  transition-timing-function: ease-in-out;\n  transition-delay: 0s;\n  pointer-events: none;\n}\n\n.code-block-container:hover .language-selector {\n  opacity: 1;\n  transition-delay: 0s;\n  pointer-events: auto;\n}\n\n.language-selector:focus-within {\n  opacity: 1;\n  transition-delay: 0s;\n  pointer-events: auto;\n}\n\n/* When mouse leaves the code block, delay the hiding */\n.code-block-container:not(:hover) .language-selector:not(:focus-within) {\n  transition-delay: 1.5s;\n}\n\n.ProseMirror pre {\n  background: #0d0d0d;\n  color: #fff;\n  font-family: ui-monospace, Menlo, Monaco, 'Cascadia Mono', 'Segoe UI Mono',\n    'Roboto Mono', 'Oxygen Mono', 'Ubuntu Mono', 'Source Code Pro', 'Fira Mono',\n    'Droid Sans Mono', 'Consolas', 'Courier New', monospace;\n  padding: 0.75rem 1rem;\n  border-radius: 0.75rem;\n  caret-color: #fff;\n}\n\n.ProseMirror pre code {\n  color: inherit;\n  padding: 0;\n  background: none;\n  font-size: 12px;\n}\n\n.ProseMirror pre .hljs-comment,\n.ProseMirror pre .hljs-quote {\n  color: #999;\n}\n\n.ProseMirror pre .hljs-variable,\n.ProseMirror pre .hljs-template-variable,\n.ProseMirror pre .hljs-attribute,\n.ProseMirror pre .hljs-tag,\n.ProseMirror pre .hljs-name,\n.ProseMirror pre .hljs-regexp,\n.ProseMirror pre .hljs-link,\n.ProseMirror pre .hljs-selector-id,\n.ProseMirror pre .hljs-selector-class {\n  color: #f2777a;\n}\n\n.ProseMirror pre .hljs-number,\n.ProseMirror pre .hljs-meta,\n.ProseMirror pre .hljs-built_in,\n.ProseMirror pre .hljs-builtin-name,\n.ProseMirror pre .hljs-literal,\n.ProseMirror pre .hljs-type,\n.ProseMirror pre .hljs-params {\n  color: #f99157;\n}\n\n.ProseMirror pre .hljs-string,\n.ProseMirror pre .hljs-symbol,\n.ProseMirror pre .hljs-bullet {\n  color: #99cc99;\n}\n\n.ProseMirror pre .hljs-title,\n.ProseMirror pre .hljs-section {\n  color: #ffcc66;\n}\n\n.ProseMirror pre .hljs-keyword,\n.ProseMirror pre .hljs-selector-tag {\n  color: #6196cc;\n}\n\n.ProseMirror pre .hljs-emphasis {\n  font-style: italic;\n}\n\n.ProseMirror pre .hljs-strong {\n  font-weight: 700;\n}\n</style>\n"